'use strict';
// Existing Q0 plans, dispatched through the complete production CPU DOM host.
// This intentionally uses a CPU-specific envelope, never the trusted-browser
// makeReceipt envelope. No browser, WebGL, network, or listener is launched.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const repo=path.resolve(__dirname,'../repo');
const core=require(path.join(repo,'tools/sim-upgrade-qualification/core.js'));
const {actionPlans,evaluateAction,PRODUCER_VERSION}=require(path.join(repo,'tools/sim-upgrade-qualification/actions.js'));
const {mountProduction}=require(path.join(repo,'tests/helpers/production-sim2-dom.cjs'));
const expectedHead='887b3181db99aa5d1c5ad6e10ab2f633f740897d';
const out=__dirname,runId='cpu-full-pr-887b318-20261003-2354';
const clone=x=>JSON.parse(JSON.stringify(x));
const git=(...args)=>cp.execFileSync('git',args,{cwd:repo,encoding:'utf8'}).trim();
const write=(name,value)=>fs.writeFileSync(path.join(out,name),JSON.stringify(value,null,2)+'\n');
const shaFile=file=>core.sha256(fs.readFileSync(file));
const collectorInputs=['actions','browser','core','run','server'].map(f=>'tools/sim-upgrade-qualification/'+f+'.js');
const harnessInputs=['tests/helpers/production-sim2-dom.cjs','tests/sim-upgrade-qualification.test.js','tests/sim-production-controls.test.js'];
const scope='Actual production Sim2 controls, core clock and route handlers in the supplied CPU recording DOM host; bounded formulas, text transitions and recorded SVG attributes only';
const limitations=[
  'No browser launched; no trusted native input, native range/number sanitization, pointer/touch/AT or browser DOM/layout measurement',
  'CPU recording DOM nodes expose fixed 640x440 rectangles and reduced-motion=true; no responsive/zoom, pixels, screenshots or visual overlap evidence',
  'Sim3 bridge endpoints are CPU stubs in this host; no Three renderer, WebGL/GPU/context recovery or resource/performance acceptance',
  'No formal academic/learner effectiveness acceptance; action oracles are bounded to existing Q0 plans and checks',
  'Source hashes establish byte currentness and replayability, not cryptographic authentication of execution'
];
const selectors=['.sim2-ic-radius-guide','.sim2-action-reaction-pair','.sim2-graph-reference','.sim2-graph'];
const controlId=n=>n.dataset.id||n.dataset.numberFor||n.dataset.controlId||n.id||null;
const label=n=>n.getAttribute('aria-label')||n.textContent.trim();
const actions=h=>h.nodes().filter(n=>n.tag==='button'&&(n.getAttribute('data-action')!==null||n.classList.contains('sim2-action')));
const getClass=(h,c)=>h.nodes().filter(n=>n.classList.contains(c));
function exactlyOne(nodes,what){if(nodes.length!==1)throw Error(what+': expected one, observed '+nodes.length);return nodes[0];}
function surface(h){
  const nodes=h.nodes();
  return {
    clockSeconds:h.shell.getSimulationTime(),
    readoutValues:Object.entries(h.rows()).map(([key,value])=>({key,value:String(value).trim()})),
    controlValues:nodes.filter(n=>n.tag==='input'&&['range','number'].includes(n.type)).map(n=>({id:controlId(n),type:n.type,value:String(n.value)})),
    actionValues:actions(h).map(n=>({id:n.dataset.action||null,label:label(n)})),
    geometry:selectors.flatMap(selector=>nodes.filter(n=>n.classList.contains(selector.slice(1))).map((n,index)=>({selector,index,visibility:n.getAttribute('visibility')||'visible',points:n.getAttribute('points')}))),
    playbackLabel:getClass(h,'sim2-playpause')[0]?.getAttribute('aria-label')||null
  };
}
function inventory(h){return {
  actions:actions(h).map(n=>({id:n.dataset.action||null,label:label(n),disabled:!!n.disabled,visibility:'not-evaluated-in-CPU-host'})),
  numbers:h.nodes().filter(n=>n.tag==='input'&&n.type==='number').map(n=>({id:controlId(n),min:n.min===''?null:Number(n.min),max:n.max===''?null:Number(n.max),value:String(n.value),step:String(n.step),physicalStep:n.dataset.physicalStep||null})),
  playback:!!getClass(h,'sim2-step').length
};}
function context(h){return {clockSeconds:h.shell.getSimulationTime(),playbackLabel:getClass(h,'sim2-playpause')[0]?.getAttribute('aria-label')||null,queuedAnimationFrames:h.frames.size,ownedTimers:h.timers.size,hostChildren:h.host.children.length,nodes:h.nodes().length,listenerCount:h.all.reduce((sum,n)=>sum+Object.values(n.listeners).reduce((s,list)=>s+list.length,0),0)};}
function observe(h){const state=surface(h);return {measuredAt:new Date().toISOString(),state,stateHash:core.hashJSON(state),context:context(h)};}
function dispose(h){const before=context(h);h.dispose();const after=context(h);const checks={hostCleared:after.hostChildren===0,animationFramesCleared:after.queuedAnimationFrames===0,timersCleared:after.ownedTimers===0,listenersCleared:after.listenerCount===0};return {before,after,checks,status:Object.values(checks).every(Boolean)?'pass':'fail'};}
function dispatch(h,op){
  if(op.type==='action'){
    const button=exactlyOne(actions(h).filter(n=>n.dataset.action===op.action),'action '+op.action);
    if(button.disabled)throw Error('Action disabled '+op.action);
    const before={id:button.dataset.action,label:label(button)};button.click();
    return {dispatch:'CPU recording-node click -> production registered event handler',button:before,cpuClickCount:1,trustedInput:false};
  }
  if(op.type==='control-value'){
    const input=exactlyOne(h.nodes().filter(n=>n.tag==='input'&&n.type==='number'&&controlId(n)===op.control),'number '+op.control),before=String(input.value);
    input.value=String(op.value);input.emit('input');input.emit('keydown',{key:'Enter'});input.emit('change');
    return {dispatch:'CPU number.value assignment + input + keydown Enter + change -> production listeners',control:op.control,requested:op.value,before,committed:String(input.value),targetReached:Number(input.value)===op.value,allowConstraintClamp:!!op.allowConstraintClamp,trustedInput:false};
  }
  if(op.type==='steps'){
    const button=exactlyOne(getClass(h,'sim2-step'),'step');for(let i=0;i<op.steps;i++)button.click();
    return {dispatch:'CPU recording-node clicks -> production step button handler',cpuClickCount:op.steps,trustedInput:false};
  }
  if(op.type==='playback-reset'){
    exactlyOne(getClass(h,'sim2-reset'),'reset').click();return {dispatch:'CPU recording-node click -> production playback reset handler',cpuClickCount:1,trustedInput:false};
  }
  if(op.type==='play-until-paused'){
    const button=exactlyOne(getClass(h,'sim2-playpause'),'play');button.click();const frames=[];
    for(let timestampMs=0;timestampMs<=op.maxWaitMs&&button.getAttribute('aria-label')==='Tạm dừng';timestampMs+=20){
      const queued=[...h.frames.entries()];h.frames.clear();for(const [,callback]of queued)callback(timestampMs);
      frames.push({timestampMs,callbacks:queued.length,clockSeconds:h.shell.getSimulationTime(),playbackLabel:button.getAttribute('aria-label')});
    }
    return {dispatch:'CPU play button click + deterministic RAF timestamps through production clock until observed pause',cpuClickCount:1,maxWaitMs:op.maxWaitMs,rafObservations:frames,terminalPlaybackLabel:button.getAttribute('aria-label'),selfPaused:button.getAttribute('aria-label')==='Chạy',trustedInput:false};
  }
  throw Error('Unhandled existing operation '+op.type);
}
async function main(){
  const startedAt=new Date().toISOString(),headBefore=git('rev-parse','HEAD'),statusBefore=git('status','--porcelain');
  if(headBefore!==expectedHead||statusBefore)throw Error('Candidate is not clean pinned HEAD');
  const product=core.sourceSnapshot(repo),collector=core.sourceSnapshot(repo,collectorInputs),harness=core.sourceSnapshot(repo,harnessInputs),replayHash=shaFile(__filename);
  const provenance={runId,head:headBefore,sourceHash:product.sourceHash,collectorHash:collector.sourceHash,harnessHash:harness.sourceHash,replayHash,producerVersion:PRODUCER_VERSION,method:'production-cpu-dom-action-replay-v1',formalAcceptance:'pending'};
  const files=[...collectorInputs,...harnessInputs,'js/sim2/sim2-route-manifest.js'];
  write('action-replay-source-bundle.json',{...provenance,product,collector,harness,replay:{path:path.basename(__filename),sha256:replayHash,source:fs.readFileSync(__filename,'utf8')},producerSources:files.map(p=>({path:p,sha256:shaFile(path.join(repo,p)),source:fs.readFileSync(path.join(repo,p),'utf8')}))});
  const routes=[],failures=[];
  for(const route of core.routes().filter(r=>r.engine==='sim2')){
    const h0=mountProduction(route.id);await Promise.resolve();
    const controls=inventory(h0),plans=actionPlans(route.id,controls),initialState=observe(h0),inventoryDisposal=dispose(h0);
    if(inventoryDisposal.status!=='pass')failures.push({route:route.id,stage:'inventory-dispose'});
    const record={...provenance,route:route.id,engine:'sim2',scope,limitations,inventory:controls,initialState,inventoryDisposal,cases:[],coverage:{discoveredActionIds:controls.actions.map(a=>a.id),plannedActionIds:[...new Set(plans.flatMap(p=>p.operations.filter(o=>o.type==='action').map(o=>o.action)))],executedActionIds:[]}};
    const seen=new Set();
    for(const plan of plans){
      const caseRecord={plan:clone(plan),status:plan.unavailableReason?'not-run':'executed',baseline:null,operations:[],disposal:null,error:null};record.cases.push(caseRecord);
      if(plan.unavailableReason){failures.push({route:route.id,case:plan.id,reason:plan.unavailableReason});continue;}
      const h=mountProduction(route.id);await Promise.resolve();caseRecord.baseline=observe(h);
      try {
        for(const requested of plan.operations){
          const before=observe(h),actual=dispatch(h,requested),immediate=observe(h);
          // Same collector-pause distinction as the existing qualification test;
          // immediate captures replay-running/self-paused state before shell.stop.
          h.shell.stop();const after=observe(h),oracle=evaluateAction(route.id,requested,before.state,after.state,{baseline:caseRecord.baseline.state,immediate:immediate.state});
          const operation={index:caseRecord.operations.length,requested:clone(requested),actual,before,immediate,after,collectorPause:{method:'production shell.stop',cpuOnly:true},oracle,oracleHash:core.hashJSON(oracle)};
          caseRecord.operations.push(operation);if(requested.type==='action')seen.add(requested.action);
          if(oracle.status==='fail')failures.push({route:route.id,case:plan.id,operation:operation.index,requested,checks:oracle.checks.filter(c=>!c.pass)});
        }
      }catch(error){caseRecord.status='error';caseRecord.error={name:error.name,message:error.message,stack:error.stack};failures.push({route:route.id,case:plan.id,error:caseRecord.error});}
      finally{caseRecord.disposal=dispose(h);if(caseRecord.disposal.status!=='pass')failures.push({route:route.id,case:plan.id,stage:'dispose'});}
    }
    record.coverage.executedActionIds=[...seen];record.coverage.missingActionIds=controls.actions.map(a=>a.id).filter(id=>!seen.has(id));
    if(record.coverage.missingActionIds.length)failures.push({route:route.id,stage:'action-coverage',missing:record.coverage.missingActionIds});
    const operations=record.cases.flatMap(c=>c.operations);
    record.summary={cases:record.cases.length,executedCases:record.cases.filter(c=>c.status==='executed').length,operations:operations.length,oracleStatuses:{pass:operations.filter(o=>o.oracle.status==='pass').length,fail:operations.filter(o=>o.oracle.status==='fail').length,'not-evaluated':operations.filter(o=>o.oracle.status==='not-evaluated').length},boundedChecks:operations.reduce((n,o)=>n+o.oracle.checks.length,0),failedChecks:operations.flatMap(o=>o.oracle.checks).filter(c=>!c.pass).length};
    const filename='action-replay-route-'+route.id+'.json';write(filename,record);routes.push({route:route.id,file:filename,sha256:shaFile(path.join(out,filename)),...record.summary});
  }
  const verification=[];
  for(const route of routes){
    const record=JSON.parse(fs.readFileSync(path.join(out,route.file),'utf8'));
    for(const c of record.cases){
      if(c.baseline&&core.hashJSON(c.baseline.state)!==c.baseline.stateHash)verification.push(route.route+'/'+c.plan.id+': baseline state hash');
      if(c.status==='executed'&&c.operations.length!==c.plan.operations.length)verification.push(route.route+'/'+c.plan.id+': operation count');
      let prior=c.baseline?.stateHash;
      for(const o of c.operations){
        if(core.hashJSON(o.requested)!==core.hashJSON(c.plan.operations[o.index]))verification.push(route.route+'/'+c.plan.id+': requested order');
        if(o.before.stateHash!==prior)verification.push(route.route+'/'+c.plan.id+': state chain');
        for(const k of ['before','immediate','after'])if(core.hashJSON(o[k].state)!==o[k].stateHash)verification.push(route.route+'/'+c.plan.id+': '+k+' state hash');
        const recalculated=evaluateAction(record.route,o.requested,o.before.state,o.after.state,{baseline:c.baseline.state,immediate:o.immediate.state});
        if(core.hashJSON(recalculated)!==o.oracleHash||core.hashJSON(o.oracle)!==o.oracleHash)verification.push(route.route+'/'+c.plan.id+': oracle recomputation');
        prior=o.after.stateHash;
      }
    }
  }
  const headAfter=git('rev-parse','HEAD'),statusAfter=git('status','--porcelain'),sourceVerification={product:core.verifySource(repo,product),collector:core.verifySource(repo,collector),harness:core.verifySource(repo,harness),replayUnchanged:shaFile(__filename)===replayHash,headBefore,headAfter,statusBefore,statusAfter};
  if(headAfter!==headBefore||statusAfter||!sourceVerification.replayUnchanged||[...sourceVerification.product,...sourceVerification.collector,...sourceVerification.harness].length)failures.push({stage:'source-currentness',sourceVerification});
  if(verification.length)failures.push({stage:'receipt-revalidation',errors:verification});
  const sum=key=>routes.reduce((n,r)=>n+r[key],0),sumStatus=key=>routes.reduce((n,r)=>n+r.oracleStatuses[key],0);
  const summary={...provenance,startedAt,finishedAt:new Date().toISOString(),node:process.version,scope,limitations,routes:routes.length,cases:sum('cases'),executedCases:sum('executedCases'),operations:sum('operations'),oracleStatuses:{pass:sumStatus('pass'),fail:sumStatus('fail'),'not-evaluated':sumStatus('not-evaluated')},boundedChecks:sum('boundedChecks'),failedChecks:sum('failedChecks'),routeReceipts:routes,receiptRevalidation:{status:verification.length?'fail':'pass',errors:verification},sourceVerification,failures,status:failures.length?'fail':'pass'};
  write('action-replay-summary.json',summary);console.log(JSON.stringify(summary,null,2));if(failures.length)process.exitCode=1;
}
main().catch(error=>{console.error(error);process.exitCode=1;});

