    assert.deepEqual(core.verifySource(core.ROOT,collector),[]);assert.ok(!fs.readdirSync(runPath).some(f=>f.endsWith('.png')));
  }finally{Module._load=load;http.createServer=server;fs.rmSync(dir,{recursive:true,force:true});}
});

